"use client"

import { useState } from "react"
import Link from "next/link"
import { Card } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar"
import { Home, Map, Lightbulb, User, Camera } from "lucide-react"
import { useAuth } from "@/context/auth-context"
import LoginScreen from "@/components/login-screen"
import CitizenApp from "@/components/citizen-app"
import ManagerDashboard from "@/components/manager-dashboard"
import CrewTaskList from "@/components/crew-task-list"

export default function HomePage() {
  const { userRole } = useAuth()
  const [activeTab, setActiveTab] = useState("home")

  if (userRole === null) {
    return <LoginScreen />
  }

  if (userRole === "Citizen") {
    return <CitizenApp />
  }

  if (userRole === "Manager") {
    return <ManagerDashboard />
  }

  if (userRole === "Crew") {
    return <CrewTaskList />
  }

  return (
    <div className="h-screen bg-background flex flex-col">
      {/* Header */}
      <div className="px-6 pt-6 pb-4 border-b border-border">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-foreground">Good morning, Ahmed</h1>
            <p className="text-muted-foreground text-sm">Let's make our city better today</p>
          </div>
          <Avatar className="h-10 w-10">
            <AvatarImage src="https://api.dicebear.com/9.x/avataaars/svg?seed=Ahmed" />
            <AvatarFallback>A</AvatarFallback>
          </Avatar>
        </div>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto px-6 py-6 pb-32">
        {/* Stats Cards */}
        <div className="grid grid-cols-2 gap-4 mb-8">
          <Card className="p-4 bg-card border-border">
            <div className="flex flex-col items-center text-center">
              <p className="text-3xl font-bold text-primary mb-1">12</p>
              <p className="text-xs text-muted-foreground font-medium">Reports Submitted</p>
            </div>
          </Card>
          <Card className="p-4 bg-card border-border">
            <div className="flex flex-col items-center text-center">
              <p className="text-3xl font-bold text-accent mb-1">5</p>
              <p className="text-xs text-muted-foreground font-medium">Issues Fixed</p>
            </div>
          </Card>
        </div>

        {/* Hero Action */}
        <Link href="/report" className="block">
          <Button className="w-full h-32 bg-primary hover:bg-primary/90 text-primary-foreground rounded-xl flex flex-col items-center justify-center gap-3 shadow-lg active:scale-95 transition-transform">
            <Camera className="h-8 w-8" />
            <span className="text-lg font-semibold">Report an Issue</span>
          </Button>
        </Link>
      </div>

      {/* Bottom Navigation */}
      <div className="fixed bottom-0 left-0 right-0 bg-card border-t border-border flex items-center justify-around">
        <Link href="/citizen-app" onClick={() => setActiveTab("home")}>
          <button
            className={`flex flex-col items-center justify-center w-20 h-20 ${activeTab === "home" ? "text-primary" : "text-muted-foreground"}`}
          >
            <Home className="h-6 w-6" />
            <span className="text-xs mt-1">Home</span>
          </button>
        </Link>
        <Link href="/map" onClick={() => setActiveTab("map")}>
          <button
            className={`flex flex-col items-center justify-center w-20 h-20 ${activeTab === "map" ? "text-primary" : "text-muted-foreground"}`}
          >
            <Map className="h-6 w-6" />
            <span className="text-xs mt-1">Map</span>
          </button>
        </Link>
        <Link href="/citizen-app" onClick={() => setActiveTab("suggestions")}>
          <button
            className={`flex flex-col items-center justify-center w-20 h-20 ${activeTab === "suggestions" ? "text-primary" : "text-muted-foreground"}`}
          >
            <Lightbulb className="h-6 w-6" />
            <span className="text-xs mt-1">Suggestions</span>
          </button>
        </Link>
        <Link href="/citizen-app" onClick={() => setActiveTab("profile")}>
          <button
            className={`flex flex-col items-center justify-center w-20 h-20 ${activeTab === "profile" ? "text-primary" : "text-muted-foreground"}`}
          >
            <User className="h-6 w-6" />
            <span className="text-xs mt-1">Profile</span>
          </button>
        </Link>
      </div>
    </div>
  )
}
